  "excludes.advisoryImmichDb": "Immich ține albumele, fețele și data fiecărei fotografii într-o bază de date PostgreSQL care rulează în alt container, nu în acesta, așa că această copie de rezervă nu o conține. O restaurare de aici aduce pozele înapoi, dar fără toate acestea. BombVault face singur dump containerului acelei baze de date când îi face backup, așa că verifică dacă este în programul tău.",
