  "dbdump.importRefused.versionSameMajor": "Serverul rulează versiunea {server}, copia vine din {dump}. MySQL și MariaDB importă un dump doar în versiunea majoră din care provine, așa că folosește pentru acest import o imagine cu versiunea {dump}.",
