  "mcp.copySettings": "Copiază setările",
  "mcp.setupCommand": "Rulează asta o dată într-un terminal.",
  "mcp.setupFile": "Adaugă asta în fișierul de configurare, lângă serverele care sunt deja acolo.",
  "mcp.setupFileUi": "În {app}, {ui} deschide fișierul.",
  "mcp.setupPaste": "O poți și lipi în {app} la {ui}.",
  "mcp.setupForm": "Introdu aceste valori în {app} la {ui}.",
  "mcp.setupOther": "Merge orice client care vorbește Streamable HTTP. Introdu asta acolo unde cere un server MCP la distanță, cu cheia în oricare dintre cele două antete.",
  "mcp.setupWhere": "Unde se află fișierul",
  "mcp.setupNeedsNode": "Are nevoie de Node.js, pentru că mcp-remote conectează {app} la BombVault.",
  "mcp.keyFileLine": "Salvează cheia într-un fișier text ca linia X-API-Key: <key> și pune calea acelui fișier în configurație. {app} păstrează doar calea, așa că cheia nu apare nici acolo, nici în lista de procese.",
  "mcp.keyFileJsonTip": "În acest fișier JSON, scrie căile cu bare oblice normale, de exemplu C:/Users/sam/bombvault-key.txt, pentru că o singură bară oblică inversă nu este JSON valid. Păstrează calea fișierului cu cheia fără spații: pe Windows, {app} îi transmite lui npx o cale cu spațiu în două bucăți.",
  "mcp.keyEnv": "{app} citește cheia din variabila de mediu {var}.",
  "mcp.keyEnvTip": "Setează-o o dată ca variabilă de mediu a utilizatorului: în Windows la Setări, Sistem, Despre, Setări complexe de sistem, Variabile de mediu; în macOS și Linux în profilul shell-ului tău. Apoi repornește {app}. Dacă o tastezi cu setx sau export într-un prompt, cheia rămâne în istoricul shell-ului. O aplicație pornită din Dock sau Finder pe macOS nu citește profilul shell-ului: pune doar cheia într-un fișier ca ~/.bombvault-key, rulează în Terminal launchctl setenv {var} \"$(cat ~/.bombvault-key)\" și redeschide {app}, din nou după fiecare repornire a Mac-ului.",
  "mcp.keyEnvUnsure": "Dacă {app} trimite numele variabilei în loc de cheie, scrie cheia în fișier în locul ei și păstrează acel fișier doar pentru tine.",
  "mcp.keyPrompt": "{app} cere cheia la prima pornire a serverului și o păstrează în propriul depozit de secrete, deci fișierul nu conține nicio cheie.",
  "mcp.keyDotenv": "{app} citește cheia din linia {var}=<key> din {file}. Păstrează acel fișier doar pentru tine.",
  "mcp.keyInFile": "{app} nu poate citi cheia de nicăieri altundeva, așa că ea stă în text simplu în acest fișier. Păstrează fișierul doar pentru tine, în afara folderelor partajate și a controlului versiunilor.",
  "mcp.keyInApp": "{app} păstrează cheia în propriile setări, necriptată după cât spune documentația lui. Oricine poate deschide acele setări o poate citi.",
  "mcp.keyCredential": "{app} păstrează cheia criptată printre datele sale de autentificare: creează cu ea o intrare de tip Bearer Auth și alege-o pe nod. Workflow-ul numește doar intrarea.",
  "mcp.keyVendor": "{app} păstrează cheia pe serverele furnizorului său și o trimite la fiecare apel.",
  "mcp.keyOther": "Dacă clientul poate citi cheia dintr-o variabilă de mediu, dintr-o solicitare de secret sau din breloul sistemului, folosește asta în loc să scrii cheia în setările lui.",
  "mcp.certPlaceholder": "BombVault folosește un certificat propriu. Configurația îndreaptă Node.js spre el: descarcă fișierul și pune calea lui în locul substituentului pentru certificat.",
  "mcp.certEnv": "BombVault folosește un certificat propriu. Dacă {app} îl respinge, setează variabila de mediu {var} la calea fișierului descărcat și repornește {app}.",
  "mcp.certEnvTip": "Seteaz-o acolo unde setezi variabilele de mediu ale utilizatorului: în Windows la Setări, Sistem, Despre, Setări complexe de sistem, Variabile de mediu; în macOS și Linux în profilul shell-ului tău; pentru un container, în setările lui, cu fișierul montat înăuntru. Descarcă din nou certificatul ori de câte ori BombVault emite unul nou. O aplicație pornită din Dock sau Finder pe macOS nu citește profilul shell-ului: pentru ea, rulează în Terminal launchctl setenv {var} cu calea fișierului și redeschide aplicația, din nou după fiecare repornire a Mac-ului.",
  "mcp.certSystem": "BombVault folosește un certificat propriu. Dacă {app} îl respinge, adaugă fișierul descărcat la certificatele de încredere ale sistemului și repornește {app}.",
  "mcp.certSystemTip": "În Windows, redenumește fișierul în bombvault-cert.crt, deschide-l și alege Instalare certificat, Utilizator curent, Se plasează toate certificatele în următorul depozit, Autorități de certificare rădăcină de încredere. Sau rulează certutil -user -addstore Root cu calea fișierului. În macOS, adaugă-l în breloul de autentificare din Acces la brelocuri și setează-l pe Ai încredere întotdeauna. În Linux, copiază-l în /usr/local/share/ca-certificates cu extensia .crt și rulează update-ca-certificates.",
  "mcp.certOwnList": "BombVault folosește un certificat propriu, iar {app} verifică certificatele după o listă proprie în care nu se poate adăuga nimic. Dacă îl respinge pe cel al BombVault, ajungi la BombVault printr-un proxy invers cu un certificat de încredere publică.",
  "mcp.certOther": "BombVault folosește un certificat propriu. Indică clientului fișierul descărcat sau adaugă-l la certificatele de încredere ale sistemului.",
  "mcp.certOtherTip": "Un client pe Node.js ia fișierul din NODE_EXTRA_CA_CERTS. Majoritatea celorlalți clienți folosesc certificatele în care are încredere sistemul. Nu dezactiva niciodată verificarea certificatelor.",
  "mcp.waitTitle": "Se așteaptă primul apel",
  "mcp.connectedTitle": "Conectat",
