  "mcp.setupChatGPT": "În ChatGPT deschide Setări, Aplicații și conectori și activează modul dezvoltator la Setări avansate. Apoi alege Creează, dă-i un nume conectorului, lipește URL-ul conectorului ca URL al serverului MCP, alege OAuth ca autentificare, confirmă că ai încredere în el și creează-l.",
