  "anomaly.settings.title": "Anomalii",
  "anomaly.settings.hint": "Compară fiecare copie a unui element cu propriul lui istoric și raportează ce nu se potrivește. Rulează în fundal după fiecare copie și nu încetinește niciuna. Majoritatea verificărilor încep după 10 copii ale unui element; eșecurile, rescrierea majorității datelor și o sursă aproape goală sunt verificate de la început. Spațiul liber este urmărit pentru depozitele locale și pentru depozitele rclone care îl raportează; pe partajarea de utilizator Unraid este spațiul liber al întregii matrice.",
  "anomaly.settings.toggle": "Detectează anomalii",
  "anomaly.settings.sensitivity": "Sensibilitate",
  "anomaly.settings.sensitivityHint": "Strictă raportează și schimbări mai mici, Permisivă doar pe cele mari, Echilibrată se potrivește majorității serverelor. Fiecare element poate avea propria setare în Anomalii, Monitorizare.",
  "anomaly.settings.notifyMin": "Trimite o notificare pentru",
  "anomaly.settings.notifyHint": "Folosește canalele configurate la Notificări. Fiecare element poate schimba asta în Anomalii, Monitorizare. Eșecurile repetate ale copiilor și dump-urilor și verificările de restaurare programate eșuate trimit deja propriul mesaj, deci nu sunt trimise a doua oară.",
  "anomaly.settings.notifyMuted": "Momentan nu se trimite nimic: notificările sunt oprite sau nu este configurat niciun canal.",
  "anomaly.settings.openNotifications": "Deschide setările notificărilor",
  "anomaly.settings.holdToggle": "Păstrează copiile vechi când o sursă se micșorează brusc sau este rescrisă",
  "anomaly.settings.holdHint": "Trei constatări opresc ștergerea copiilor vechi: o sursă care dintr-odată este aproape goală, una care a devenit mult mai mică și o copie care a salvat din nou majoritatea datelor, așa cum arată un ransomware. Altfel păstrarea ar șterge copiile vechi bune una câte una. Cât timp o astfel de anomalie este deschisă, se păstrează copiile vechi doar ale acelui element (sau ale acelui dump de bază de date sau set de date ZFS); tot restul se curăță ca de obicei. Confirmă anomalia sau marcheaz-o ca așteptată ca să continue.",
